def transform(grid):
    out = [row[:] for row in grid]
    cells = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 5]
    r0 = min(r for r, c in cells)
    r1 = max(r for r, c in cells)
    c0 = min(c for r, c in cells)
    c1 = max(c for r, c in cells)

    # The first inner border is color 2. Further color-5 borders are
    # separated by one untouched layer.
    inset = 1
    while True:
        top, bottom = r0 + inset, r1 - inset
        left, right = c0 + inset, c1 - inset
        h, w = bottom - top + 1, right - left + 1
        if h <= 0 or w <= 0:
            break

        if inset == 1:
            color = 2
        elif inset % 2 == 0:
            color = 5
        else:
            inset += 1
            continue

        if h == 2 and w == 2:
            for r in range(top, bottom + 1):
                for c in range(left, right + 1):
                    out[r][c] = color
            break
        if h <= 2 or w <= 2:
            break

        for c in range(left, right + 1):
            out[top][c] = color
            out[bottom][c] = color
        for r in range(top, bottom + 1):
            out[r][left] = color
            out[r][right] = color
        inset += 1
    return out
